<section class="page-head"><div><p class="eyebrow">Catalog structure</p><h1>Categories</h1><p class="muted">Organize products into clear, mobile-friendly groups.</p></div><a class="button primary" href="/categories/create">Add category</a></section>
<?php if(!$categories):?><section class="empty-state panel"><div class="empty-icon">◇</div><h2>Your catalog has no categories</h2><p>Create the first category, then start adding products.</p><a class="button primary" href="/categories/create">Create first category</a></section><?php else:?><section class="panel flush"><div class="list-head"><span><?= count($categories) ?> categories</span><small>Use arrows to control storefront order.</small></div><div class="category-list"><?php foreach($categories as$i=>$category):?><article class="category-row"><div class="row-order"><form method="post" action="/categories/<?= e($category['id']) ?>/move"><?= csrf_field() ?><input type="hidden" name="direction" value="up"><button class="icon-button" aria-label="Move <?= e($category['name']) ?> up" <?= $i===0?'disabled':'' ?>>↑</button></form><form method="post" action="/categories/<?= e($category['id']) ?>/move"><?= csrf_field() ?><input type="hidden" name="direction" value="down"><button class="icon-button" aria-label="Move <?= e($category['name']) ?> down" <?= $i===count($categories)-1?'disabled':'' ?>>↓</button></form></div><?php if($category['image_path']):?><img class="category-list-image" src="<?= e($category['image_path']) ?>" alt=""><?php else:?><span class="category-list-image placeholder" aria-hidden="true">◇</span><?php endif ?><div class="category-main"><strong><?= e($category['name']) ?></strong><span>/<?= e($category['slug']) ?> · <?= e($category['product_count']) ?> products</span></div><span class="badge <?= strtolower($category['status']) ?>"><?= e($category['status']) ?></span><div class="row-actions"><a class="button compact secondary" href="/categories/<?= e($category['id']) ?>/edit">Edit</a><form method="post" action="/categories/<?= e($category['id']) ?>/toggle"><?= csrf_field() ?><button class="button compact ghost"><?= $category['status']==='ACTIVE'?'Hide':'Activate' ?></button></form><form method="post" action="/categories/<?= e($category['id']) ?>/delete" data-confirm="Delete category?" data-confirm-message="This category will be removed. Categories containing products cannot be deleted."><?= csrf_field() ?><button class="button compact danger-ghost">Delete</button></form></div></article><?php endforeach ?></div></section><?php endif ?>
